[{"order":1,"type":"heading","text":"Mastering HTTP Methods and Semantics in REST APIs"},{"order":2,"type":"paragraph","text":"HTTP methods form the foundational contract between clients and servers in RESTful architecture. Understanding their semantics ensures your API is predictable, scalable, and compliant with web standards."},{"order":3,"type":"subheading","text":"Safe vs. Idempotent Methods"},{"order":4,"type":"paragraph","text":"Before diving into individual methods, two critical concepts define HTTP semantics: Safety and Idempotency."},{"order":5,"type":"bullet_point","text":"Safe methods (e.g., GET, HEAD) do not modify server-side state. They are read-only operations."},{"order":6,"type":"bullet_point","text":"Idempotent methods (e.g., GET, PUT, DELETE) can be applied multiple times with the same result as a single application."},{"order":7,"type":"subheading","text":"Core HTTP Methods Breakdown"},{"order":8,"type":"bullet_point","text":"GET: Retrieves a resource or a collection of resources. It must be safe and idempotent."},{"order":9,"type":"bullet_point","text":"POST: Creates a new subordinate resource. It is neither safe nor idempotent."},{"order":10,"type":"bullet_point","text":"PUT: Replaces an existing resource entirely or creates it if it does not exist. It is idempotent."},{"order":11,"type":"bullet_point","text":"PATCH: Applies partial modifications to a resource."},{"order":12,"type":"bullet_point","text":"DELETE: Removes the specified resource. It is idempotent."},{"order":13,"type":"bullet_point","text":"HEAD: Identical to GET, but transfers only the status line and header section, without the response body."},{"order":14,"type":"bullet_point","text":"OPTIONS: Describes the communication options for the target resource, often used in CORS preflight requests."},{"order":15,"type":"subheading","text":"Practical Express.js Example"},{"order":16,"type":"paragraph","text":"The following code snippet demonstrates how different HTTP methods are mapped in a Node.js Express API."},{"order":17,"type":"code","text":"const express = require('express');
const app = express();
app.use(express.json());

app.get('/api/users', (req, res) => {
  res.status(200).json([{ id: 1, name: 'Alice' }]);
});

app.post('/api/users', (req, res) => {
  const newUser = { id: Date.now(), ...req.body };
  res.status(201).json(newUser);
});

app.put('/api/users/:id', (req, res) => {
  res.status(200).json({ id: req.params.id, ...req.body });
});

app.delete('/api/users/:id', (req, res) => {
  res.status(204).send();
});

app.listen(3000);"},{"order":18,"type":"subheading","text":"Summary of Best Practices"},{"order":19,"type":"bullet_point","text":"Never use GET for state-changing operations."},{"order":20,"type":"bullet_point","text":"Use PUT for complete replacements and PATCH for partial updates."},{"order":21,"type":"bullet_point","text":"Always return appropriate status codes (e.g., 201 Created for POST, 204 No Content for successful DELETE)."}]
